<?php
$search=trim($_GET['q']??''); $cat=(int)($_GET['category']??0); $status=$_GET['status']??''; $sql='SELECT i.id,i.asset_code,i.status,i.condition_label,i.notes,e.name,e.category_id,c.name category FROM equipment_items i JOIN equipment e ON e.id=i.equipment_id JOIN equipment_categories c ON c.id=e.category_id WHERE 1=1'; $args=[]; if($search!==''){ $sql.=' AND (e.name LIKE ? OR i.asset_code LIKE ?)'; $args[]="%$search%";$args[]="%$search%";} if($cat){$sql.=' AND c.id=?';$args[]=$cat;} if(in_array($status,['Available','On Loan','Awaiting Inspection','Under Repair','Retired'],true)){$sql.=' AND i.status=?';$args[]=$status;} $sql.=' ORDER BY e.name,i.asset_code';$s=$pdo->prepare($sql);$s->execute($args);$rows=$s->fetchAll();$categories=$pdo->query('SELECT id,name FROM equipment_categories ORDER BY name')->fetchAll();
layout_start('Equipment','equipment'); ?><div class="page-heading"><div><p class="eyebrow">INVENTORY</p><h1>Equipment</h1><p class="muted">Track every reusable item, its condition and availability.</p></div><a class="button primary" href="?page=equipment-form">＋ Add equipment</a></div><section class="panel"><form class="filter-bar" method="get"><input type="hidden" name="page" value="equipment"><label class="search-box"><span>⌕</span><input name="q" placeholder="Search name or asset ID" value="<?=h($search)?>"></label><select name="category"><option value="0">All categories</option><?php foreach($categories as $c): ?><option value="<?=$c['id']?>" <?=$cat===$c['id']?'selected':''?>><?=h($c['name'])?></option><?php endforeach; ?></select><select name="status"><option value="">All statuses</option><?php foreach(['Available','On Loan','Awaiting Inspection','Under Repair','Retired'] as $st): ?><option <?=$status===$st?'selected':''?>><?=h($st)?></option><?php endforeach; ?></select><button class="button secondary">Filter</button><a class="button ghost" href="?page=equipment">Reset</a></form><div class="table-scroll"><table><thead><tr><th>Equipment</th><th>Asset ID</th><th>Category</th><th>Condition</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><strong><?=h($r['name'])?></strong><small class="cell-sub"><?=h($r['notes']??'')?></small></td><td><?=h($r['asset_code'])?></td><td><?=h($r['category'])?></td><td><?=h($r['condition_label'])?></td><td><span class="badge <?=strtolower(str_replace(' ','-',$r['status']))?>"><?=h($r['status'])?></span></td><td><a class="text-link" href="?page=equipment-view&id=<?=$r['id']?>">Details →</a></td></tr><?php endforeach; ?></tbody></table><?php if(!$rows): ?><div class="table-empty">No equipment matches these filters.</div><?php endif; ?></div></section><?php layout_end();
